function zoomBuildCamera(factor){
 const damping=controls.enableDamping;controls.enableDamping=false;controls.update();
 const offset=camera.position.clone().sub(controls.target),distance=offset.length();
 if(distance>0)camera.position.copy(controls.target).add(offset.multiplyScalar(THREE.MathUtils.clamp(distance*factor,controls.minDistance,controls.maxDistance)/distance));
 controls.update();controls.enableDamping=damping;
}


