function selectLayout(layout){
 if(!layouts[layout])return;
 if(layouts[layout].canonicalLayout)layout=layouts[layout].canonicalLayout;
 if(SCENE_SOURCE_IDS[layout]){beginPlacement(SCENE_SOURCE_IDS[layout]);return;}
 if(layouts[layout].environmentId){showRepositoryMap(layout);return;}
 if(layout==='missile-factory'){generateFactoryWorld();return;}
 if(layout==='fitness-centre'){generateFitnessWorld();return;}
 closeRepositoryMap();
 if(URBAN_LAYOUTS[layout]||BUILDING_DISTRICTS[layout]||CAMP_LAYOUTS[layout])generateUrbanWorld(layout);
 else {clearBaseWorld();delete sceneData.baseEnvironment;if(sceneData.sourceLayout==='missile-factory'){delete sceneData.sourceLayout;delete sceneData.sourceGame;delete sceneData.sourceFactory;delete sceneData.sourceEnvironmentId;delete sceneData.sourceSpawn;if(sceneData.layoutMeta)delete sceneData.layoutMeta.factory;if(sceneData.gameplay)delete sceneData.gameplay.factory;}if(sceneData.sourceLayout==='fitness-centre'){delete sceneData.sourceLayout;delete sceneData.sourceGame;delete sceneData.sourceFitness;delete sceneData.sourceEnvironmentId;delete sceneData.sourceSpawn;if(sceneData.layoutMeta)delete sceneData.layoutMeta.fitness;if(sceneData.gameplay)delete sceneData.gameplay.fitness;}updateLayout(layout);resetBuildView();}
}
