function qualityResults(){
 const arcade=sceneData.layout==='arcade-park'?arcadeSettings(sceneData.gameplay?.arcade):null,parkParts=arcade?ARCADE_PARTS.filter(part=>!part.placeableOnly&&arcade.parts[part.id]?.enabled!==false):[],parkAttractions=arcade?arcade.enabled.filter(id=>arcade.parts[id]?.enabled!==false):[],named=sceneData.name.trim()&&sceneData.name!=='Untitled environment',hasObjects=sceneData.objects.length>0||parkParts.length>0,types=new Set(sceneData.objects.map(object=>modelFor(object.modelId)?.type).filter(Boolean));
 return[
  {pass:Boolean(named),label:'Give the scene a unique name'},
  {pass:hasObjects,label:'Place at least one model'},
  {pass:types.size>1||sceneData.objects.length+parkParts.length>=3,label:'Build a varied scene with 3 objects or 2 model types'},
  {pass:sceneData.objects.every(object=>object.scale.x>=.4&&object.scale.x<=2.4),label:'Keep every model inside the playable scale range'},
  {pass:parkAttractions.length>0||sceneData.objects.some(object=>object.functionalSettings?.behavior!=='decor'),label:'Add at least one playable interaction'}
 ];
}
function renderQualityCheck(){const checks=qualityResults(),passed=checks.filter(check=>check.pass).length,score=Math.round(passed/checks.length*100);$('#quality-score').textContent=`${score}%`;$('#quality-checks').innerHTML=checks.map(check=>`<li class="${check.pass?'pass':''}">${check.label}</li>`).join('');$('#certify-scene').disabled=passed!==checks.length;if(sceneData.certification?.certified)$('#quality-status').textContent=`Certified locally · ${sceneData.certification.score}% ready`}
$('#certify-scene').addEventListener('click',()=>{const checks=qualityResults();if(checks.some(check=>!check.pass))return;sceneData.certification={certified:true,score:100,checkedAt:new Date().toISOString(),version:1};persist('Quality certified — this build is ready to share');renderQualityCheck()});

async function publishAndPlay({launch=true}={}){
 if(publishing)return;publishing=true;const buttons=[$('#publish-scene'),$('#play-scene')];buttons.forEach(button=>button.disabled=true);
 try{
  if(!sceneData.id||sceneData.id==='active')sceneData.id=`custom-map-${uid()}`;
  sceneData.gameplay={...sceneData.gameplay,multiplayer:$('#play-mode').value!=='solo'};persist(launch?'Draft saved. Preparing selected-mode test…':'Draft saved. Publishing map…');
  const inventory=new SharedGameInventory();let session=await ensurePlayAccess(inventory);if(!session){$('#save-state').textContent='Map saved · choose Play when ready';return;}
  const publish=()=>inventory.api('/api/custom-maps',{method:'POST',headers:{'X-CSRF-Token':session.csrfToken},body:JSON.stringify({scene:cloneData(sceneData)})});
  let result;try{result=await publish();}catch(error){
   if(error.status===401){session=error.code==='CSRF_INVALID'?await inventory.session():await choosePlayAccess(inventory);if(!session)return;try{result=await publish();}catch(retryError){error=retryError;}}
   if(!result&&error.code==='MAP_ID_CONFLICT'){sceneData.id=`custom-map-${uid()}`;persist('Saved a new copy for this player.');result=await publish();}
   if(!result)throw error;
  }
  const playLink=$('#published-map-link');playLink.href=result.playUrl;playLink.dataset.sceneId=sceneData.id;playLink.hidden=false;$('#builder-publish-status').textContent=`Published ${result.name||sceneData.name} · ${sceneData.gameplay.multiplayer?'Multiplayer':'Solo'} ready`;
  if(launch)window.location.assign(result.playUrl);else await refreshBuilderAccess();
 }catch(error){showToast(error.message);$('#save-state').textContent='Draft saved locally';$('#builder-publish-status').textContent=error.message;}
 finally{publishing=false;buttons.forEach(button=>button.disabled=false);}
}
