function syncArcadeSettings(){
 const panel=$('#arcade-settings');panel.hidden=sceneData.layout!=='arcade-park';$('#play-mode').disabled=false;
 const config=arcadeSettings(sceneData.gameplay?.arcade);for(const input of panel.querySelectorAll('[name]'))input.value=config[input.name]??'';
 for(const input of panel.querySelectorAll('[data-arcade-enable]'))input.checked=config.enabled.includes(input.dataset.arcadeEnable);
 for(const input of panel.querySelectorAll('[data-arcade-station]'))input.value=config.placements[input.dataset.arcadeStation][input.dataset.axis];
 const opened=new Set([...panel.querySelectorAll('[data-arcade-part-details][open]')].map(part=>part.dataset.arcadePartDetails));
 $('#arcade-part-list').innerHTML=ARCADE_PARTS.filter(part=>!part.placeableOnly).map(part=>{const transform=arcadePartTransform(config,part.id),enabled=config.parts[part.id]?.enabled!==false&&(!part.attraction||config.enabled.includes(part.id));return `<details data-arcade-part-details="${part.id}"${opened.has(part.id)?' open':''}><summary><span class="arcade-part-dot" style="background:${part.color}"></span><strong>${escapeHtml(part.name)}</strong><small>${enabled?'Enabled':'Hidden'}</small></summary><p>${escapeHtml(part.description)}</p><div class="arcade-part-fields"><label><input type="checkbox" data-arcade-part="${part.id}" data-property="enabled"${enabled?' checked':''}> Show / enable</label>${[['x','X position',arcadeStationIds.includes(part.id)?-18:-50,arcadeStationIds.includes(part.id)?18:50,.5],['z','Z position',arcadeStationIds.includes(part.id)?-11:-50,arcadeStationIds.includes(part.id)?11:50,.5],['rotation','Rotation °',-180,180,5],['scale','Scale',.5,1.75,.05]].map(([key,label,min,max,step])=>`<label>${label}<input type="number" data-arcade-part="${part.id}" data-property="${key}" value="${transform[key]}" min="${min}" max="${max}" step="${step}"></label>`).join('')}<label>Accent color<input type="color" data-arcade-part="${part.id}" data-property="color" value="${transform.color||part.color}"></label></div><div class="arcade-part-actions"><button type="button" data-arcade-focus="${part.id}">SHOW IN SCENE</button><button type="button" data-arcade-extract="${part.id}">MAKE EDITABLE ITEM</button><button type="button" data-arcade-reset="${part.id}">RESET PART</button></div></details>`}).join('');
}
function refreshArcadePreview({rebuild=false,id}={}){
 const config=sceneData.gameplay.arcade;
 const park=worldDressing.children.find(child=>child.userData.arcadePark);
 if(!rebuild&&park&&id&&updateArcadeParkPart(park,id,config))return;
 if(rebuild)addWorldDressing();
}
$('#arcade-settings').addEventListener('change',event=>{
 const panel=$('#arcade-settings'),raw=cloneData(arcadeSettings(sceneData.gameplay?.arcade)),partInput=event.target.closest('[data-arcade-part]');let partId;
 if(partInput){partId=partInput.dataset.arcadePart;const key=partInput.dataset.property;if(key==='enabled'){raw.parts[partId].enabled=partInput.checked;if(ARCADE_ATTRACTIONS.some(part=>part.id===partId))raw.enabled=partInput.checked?[...new Set([...raw.enabled,partId])]:raw.enabled.filter(id=>id!==partId);}else arcadePartTransform(raw,partId)[key]=partInput.value;}
 else{for(const input of panel.querySelectorAll('[name]'))raw[input.name]=input.value;raw.enabled=[...panel.querySelectorAll('[data-arcade-enable]:checked')].map(input=>input.dataset.arcadeEnable);for(const input of panel.querySelectorAll('[data-arcade-station]'))raw.placements[input.dataset.arcadeStation][input.dataset.axis]=input.value;if(event.target.dataset.arcadeEnable){partId=event.target.dataset.arcadeEnable;raw.parts[partId].enabled=event.target.checked;}else if(event.target.dataset.arcadeStation)partId=event.target.dataset.arcadeStation;}
 sceneData.gameplay={...sceneData.gameplay,multiplayer:$('#play-mode').value!=='solo',arcade:arcadeSettings(raw)};
 refreshArcadePreview({id:partId,rebuild:['coasterPeak','trainRadiusX','trainRadiusZ','coasterWidth','coasterDepth'].includes(event.target.name)});syncArcadeSettings();updateUi();markChanged();
});
$('#arcade-part-list').addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;const config=cloneData(arcadeSettings(sceneData.gameplay?.arcade)),id=button.dataset.arcadeFocus||button.dataset.arcadeExtract||button.dataset.arcadeReset,part=ARCADE_PARTS.find(item=>item.id===id);if(!part)return;
 if(button.dataset.arcadeFocus){const park=worldDressing.children.find(child=>child.userData.arcadePark);let target;park?.traverse(node=>{if(node.userData.arcadePart===id&&!target)target=node});if(target){const box=new THREE.Box3().setFromObject(target),center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3()).length();controls.target.copy(center);camera.position.copy(center).add(new THREE.Vector3(1,.85,1).normalize().multiplyScalar(Math.min(54,Math.max(8,size))));controls.update();showToast(`${part.name} shown in scene`)}return;}
 if(button.dataset.arcadeReset){const defaults=arcadeSettings();config.parts[id]=defaults.parts[id];if(arcadeStationIds.includes(id))config.placements[id]=defaults.placements[id];if(part.attraction&&!config.enabled.includes(id))config.enabled.push(id);sceneData.gameplay.arcade=arcadeSettings(config);refreshArcadePreview({id});syncArcadeSettings();markChanged();return;}
 const transform=arcadePartTransform(config,id),object=makeObject(`arcade-part-${id}`,transform.x,transform.z);object.rotation.y=THREE.MathUtils.degToRad(transform.rotation);object.scale={x:transform.scale,y:transform.scale,z:transform.scale};object.materialSettings={accent:transform.color||part.color,useAccent:true};object.arcadeSettings=config;sceneData.objects.push(object);selectedId=object.id;inspectorRequested=true;config.parts[id].enabled=false;if(part.attraction)config.enabled=config.enabled.filter(item=>item!==id);sceneData.gameplay.arcade=arcadeSettings(config);buildRuntime(object).then(()=>{updateUi();document.body.classList.add('inspector-open')});refreshArcadePreview({id});syncArcadeSettings();markChanged();showToast(`${part.name} is now a selectable item. Its built-in copy is hidden.`);
});
async function importPublishedEnvironment(id){
 const status=$('#builder-publish-status'),controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);status.textContent='Loading published map for customization…';
 try{let maps;try{const request=window.MUZIKAZ_API?.fetch?window.MUZIKAZ_API.fetch('/api/environments',{timeout:8000,retries:0,cache:'no-store',signal:controller.signal}):fetch('/api/environments',{cache:'no-store',signal:controller.signal});const response=await Promise.race([request,new Promise((_,reject)=>controller.signal.addEventListener('abort',()=>reject(Error('Map request timed out')),{once:true}))]);if(!response.ok)throw Error('Map service unavailable');const body=await response.json();maps=body.data||body;}catch(error){if(id!=='neon-junction')throw error;const bundled=await fetch('public/models/environments/environments.json',{cache:'no-store'});if(!bundled.ok)throw error;maps=await bundled.json();}const map=Array.isArray(maps)&&maps.find(item=>item.id===id);if(!map||!isArcadeMap(map))throw Error('This arcade map is unavailable');const imported=map.builderScene?cloneData(map.builderScene):{layout:'arcade-park',mapSize:80,objects:[],gameplay:{arcade:map.arcade}};for(const model of [...(imported.placedModels||[]),...(imported.customModels||[]),...(imported.catalogModels||[])])if(model?.id&&!modelFor(model.id))catalogModels.push(cloneData(model));renderLibrary();sceneData={...sceneData,...imported,id:`custom-map-${uid()}`,sourceEnvironmentId:id,name:`${map.name||'Neon Junction'} · Custom`,layout:'arcade-park',mapSize:Math.max(80,Number(imported.mapSize)||80),gameplay:{...imported.gameplay,multiplayer:$('#play-mode').value!=='solo',arcade:arcadeSettings(imported.gameplay?.arcade)},objects:(imported.objects||[]).filter(object=>modelFor(object.modelId)).map(migrateObject)};$('#scene-name').value=sceneData.name;$('#weather-select').value=sceneData.weather||'clear';applyMapSize(sceneData.mapSize);updateLayout('arcade-park');rebuildAll();status.textContent='Published map loaded. Your previous local draft is kept until you save this version.';showToast('Published park loaded for customization');}
 catch(error){status.textContent=`Could not load the requested park: ${error.name==='AbortError'?'request timed out':error.message}. Your local draft is still available.`;showToast('Published map could not be loaded');}
 finally{clearTimeout(timeout)}
}
syncArcadeSettings();
